export default {
  inheritAttrs: false,
  props: ['chat', 'text', 'mentionList', 'files'],
  emits: ['generate-code', 'reload-file', 'open-file', 'save-file', 'add-file', 'edit-message', 'text-changed'],
  data() {
    return {
      // localText is the mutable working copy of the markdown source
      localText: null,
      codeBlocks: [],
      showDoc: false,
      youtubeLinks: [],
    }
